import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fatiarLista } from './solution.mjs';

test('fatia um trecho do meio', () => {
  assert.deepEqual(fatiarLista([0, 1, 2, 3, 4], 1, 3), [1, 2]);
});

test('sem o fim, vai até o final; fim grande demais não quebra', () => {
  assert.deepEqual(fatiarLista([0, 1, 2, 3], 2), [2, 3]);
  assert.deepEqual(fatiarLista([0, 1], 0, 99), [0, 1]);
});

test('índice negativo conta do fim', () => {
  assert.deepEqual(fatiarLista([0, 1, 2, 3], -2), [2, 3]);
});

test('recusa valor que não é lista', () => {
  assert.throws(() => fatiarLista('0,1,2', 0, 1));
});

solutionCode:
export function fatiarLista(lista, inicio, fim) {
  if (!Array.isArray(lista)) {
    throw new Error('lista precisa ser um array');
  }
  return lista.slice(inicio, fim);
}
